      'In the same skillet, sauté the onion over medium heat until golden, about 10 minutes. Add cinnamon, turmeric, salt, and pepper. Return the lamb and stir to coat. Add ¼ cup water, cover, and simmer on low for 30–40 minutes until lamb is tender. In the last 5 minutes, add the dried fruits and chestnuts. Set aside.',
      'Bring a large pot of heavily salted water to a boil. Add the drained rice and parboil for 6–7 minutes — the rice should be about 70% cooked (tender outside, firm inside). Drain immediately.',
      'Make the gazmag crust: in a heavy-bottomed pot (kazan or Dutch oven), melt 2 tbsp butter over medium heat. Spread a thin layer of uncooked soaked rice (or a piece of lavash) across the bottom to form the crust layer.',
