    notes: 'Azerbaijan has over 40 varieties of plov, more than any other country. Azerbaijani plov is distinct from Central Asian plovs because the rice and the meat are cooked separately and brought together only at serving. The dish holds such cultural significance that UNESCO inscribed it on the Intangible Cultural Heritage list.',
