      'Pot method: cover and simmer on low heat for 25–30 minutes, stirring occasionally, until the rice and dal break down into a soft, unified mass. Add water as needed.',
      'Stir in remaining 1 tbsp ghee and garam masala.',
      'Make the tadka: heat 2 tbsp ghee in a small pan over high heat until shimmering. Add mustard seeds — let them pop. Add cumin seeds, dried chilies, curry leaves, and asafoetida. Sizzle for 10 seconds.',
      'Pour the sizzling tadka over the khichdi all at once. Stir to combine.',
      'Serve in bowls with an extra spoonful of ghee melted on top, yogurt, papad, and mango pickle alongside.',
