    notes: 'Khichdi is arguably the oldest recipe still actively cooked in the world — it is described in texts dating back 2,000 years and was eaten by the Mughal emperors. The 14th-century Moroccan traveler Ibn Battuta described eating "kishri" across India. It has been officially recognized as India\'s national dish. The English word "kedgeree" — a Victorian breakfast dish — derives directly from khichdi, brought back by British colonists. In India, khichdi is the first solid food given to babies and the last comfort food for the elderly.',
