      'Add the cold rice all at once. Break up any clumps and stir-fry vigorously, pressing and tossing the rice against the hot wok for 2–3 minutes until heated through and every grain is separate.',
      'Add kecap manis, soy sauce, and oyster sauce. Toss everything together for 1–2 minutes until the rice is evenly coated and turns a caramel-brown color.',
