    notes: 'Nasi goreng was voted the world\'s most delicious food in a 2011 CNN poll. It exists in hundreds of regional variations across Indonesia\'s 17,000 islands — nasi goreng kampung (village style), nasi goreng seafood, nasi goreng pete (with stink beans). The dish is sold from street carts (warung) at every hour — it is particularly beloved as a late-night meal. President Sukarno reportedly served nasi goreng to visiting heads of state. It is also the national dish of the Netherlands, where it arrived via colonial connections to the Dutch East Indies.',
