      'Add the fried herbs, pierced dried limes, kidney beans, and water or broth. Stir to combine.',
      'Bring to a boil, then reduce heat to the lowest possible simmer. Cover and cook for 1 hour 45 minutes to 2 hours, stirring occasionally, until the lamb is completely tender and the stew is very dark, thick, and fragrant.',
      'The dried limes will soften — press on them with the back of a spoon to release their sour juice into the stew.',
