    notes: 'Ghormeh sabzi is considered the king of Iranian cuisine and was voted Iran\'s most popular dish in multiple polls. The dish is estimated to be 2,000–5,000 years old, making it one of the oldest continuously made recipes on earth. In Iranian culture, the smell of ghormeh sabzi frying means home, warmth, and family. Iranians abroad describe it as the food they most desperately miss. It is the centerpiece of Nowruz (Persian New Year) tables across the world.',
