      '2 medium carrots, finely diced',
      '3 stalks celery, finely diced',
      '4 garlic cloves, minced',
      '3 tbsp butter',
      '2 tbsp olive oil',
      '1 cup (240ml) dry white wine',
      '1 cup (240ml) whole milk',
