    notes: 'Nsima is the lifeblood of Malawian culture — a meal without nsima is not considered a real meal. Lake Malawi, one of Africa\'s great lakes, provides the kapenta fish that frequently appears in ndiwo. Malawi is one of the world\'s most densely populated countries relative to arable land, so maize-based nsima has been the staple for generations out of both cultural preference and practical necessity. The word "ndiwo" means relish or side dish — its content varies by season and household.',
