    notes: 'Buuz are Mongolia\'s most beloved food and are eaten in enormous quantities during Tsagaan Sar (Mongolian Lunar New Year), when families steam thousands of dumplings in preparation. The dish reflects the nomadic herding culture — mutton is the dominant protein of the Mongolian steppe. Buuz are similar to the Tibetan momo and Chinese baozi, reflecting the cultural exchange across the Central Asian plateau. The open-top fold that distinguishes Mongolian buuz from other dumplings is a point of national pride.',
