    notes: 'Matapa is Mozambique\'s most iconic national dish, originating in the southern coastal region where cassava and coconut palms grow abundantly. Mozambique\'s long Indian Ocean coastline and history as a Portuguese colony (1498–1975) shaped a cuisine that blends African, Portuguese, and Indian influences — the piri piri chilli used widely in Mozambican cooking was spread by the Portuguese. Matapa is eaten at weddings and celebrations and is considered the dish that most represents Mozambican identity.',
