    notes: 'The coconut crab (Birgus latro) is sacred to Pacific Island cultures and is the largest land-living arthropod on earth, with claws strong enough to crack coconuts — its namesake. In Nauru, the world\'s third-smallest country by area and a Pacific island nation, coconut crab was once abundant but is now rare due to overhunting and habitat loss. This dish represents the island\'s traditional pre-colonial diet when seafood, coconut, and breadfruit were the entirety of nutrition. Nauru\'s modern diet has shifted dramatically toward imported processed food.',
