    notes: 'Dal bhat is Nepal\'s national dish and is eaten by virtually every Nepali family twice daily — morning and evening. The phrase "dal bhat power, 24 hour" is a saying among Nepali trekking guides and porters who credit the dish for their legendary endurance at altitude. The dish varies by region — Terai plains dal differs from hill and mountain dal — but the structure of rice + lentil soup + accompaniments is universal. It represents Nepal\'s Hindu and Buddhist food traditions, where rice and lentils have formed the dietary foundation for millennia.',
