      'Season meat generously with salt and pepper. Wrap individual portions of meat and vegetables in foil with a knob of butter, then wrap again in damp hessian sacking.',
      'Using long-handled tools or tongs, carefully lower the wrapped parcels into the pit onto the hot stones.',
      'Cover the pit with more damp hessian, then a layer of earth to seal in the steam. It must be completely sealed — no steam should escape.',
      'Cook for 3–4 hours. The steam created by the moisture in the sacking and vegetables cooks everything gently.',
      'Unseal and carefully lift out the parcels. The meat should be falling off the bone, the vegetables soft and smoky.',
      'Serve communally on large platters.',
