    tips: [
      'The key is sealing the pit completely — any steam escape will slow cooking dramatically.',
      'For a home version: a large sealed barbecue with wet wood chips and a water pan can simulate hāngī. Or use a slow cooker for 8 hours with liquid smoke.',
      'Traditional stones used are basalt or granite — avoid sedimentary rocks which can crack dangerously when heated.',
    ],
    notes: 'Hāngī is the foundational cooking method and feast of the Māori people of Aotearoa (New Zealand). The name refers to both the pit and the food cooked in it. It is used for every major celebration: weddings, funerals, festivals, and the arrival of important guests. The food cooked in a hāngī has a distinctive earthy, smoky flavour that is impossible to replicate with any other method — it is described by Māori as tasting of the whenua (land). Hāngī represents manaakitanga — the Māori concept of hospitality, generosity, and care.',
