    notes: 'Sopa Paraguaya is Paraguay\'s most iconic national dish and its unusual name — "Paraguayan soup" for something that is clearly not soup — has a legendary origin: a cook preparing corn soup for President Carlos Antonio López accidentally added too much cornmeal, creating a firm cake. The President loved it and named it "sopa." Paraguay is one of two landlocked countries in South America (along with Bolivia) and its cuisine is shaped by the indigenous Guaraní tradition — corn, cheese, and manioc are the foundational ingredients.',
