    notes: 'Paella originated in the rice paddies of Valencia in the 19th century — a farmworker\'s midday meal cooked over wood fire in the fields. The authentic Valencian version contains chicken, rabbit, and local green and white beans — no seafood. The seafood paella popular internationally is a later coastal adaptation. Paella is cooked outdoors over orange wood in Valencia for maximum flavour. The socarrat — the caramelised rice crust — is the most prized element and the test of a cook\'s skill. Arguments about authentic paella are among Spain\'s most passionate culinary debates.',
