    notes: 'Pad Thai was invented — or more accurately, popularised — by the Thai government in the 1930s–40s as part of a nationalistic campaign to create a unified Thai identity and reduce rice consumption during wartime scarcity. The dish succeeded beyond all expectation: it became Thailand\'s most emblematic food worldwide. Authentic pad thai is sold from carts across Bangkok at extraordinary speed, the wok flames visible from blocks away. Thailand\'s street food culture is among the world\'s greatest, and Bangkok consistently ranks as the world\'s top street food city.',
